export function createLedger() {
  const messages = new Map();
  const requests = [];
  const key = (scope, id) => JSON.stringify([scope, id]);

  function mergeProgress(input) {
    const matches = requests.filter((request) => request.scope === input.scope &&
      ((input.userId !== undefined && request.userId === input.userId) ||
       (input.agentId !== undefined && request.agentId === input.agentId)));
    const merged = Object.assign({}, ...matches, input, {
      completed: input.completed || matches.some((request) => request.completed),
    });
    for (const request of matches) requests.splice(requests.indexOf(request), 1);
    requests.push(merged);
  }

  return {
    accept(scope, userId) { mergeProgress({ scope, userId, completed: false }); },
    restoreMessage(message) { messages.set(key(message.scope, message.id), { ...message }); },
    receive(snapshot) {
      const previous = messages.get(key(snapshot.scope, snapshot.id));
      const stored = { ...previous, ...snapshot };
      messages.set(key(stored.scope, stored.id), stored);
      mergeProgress({
        scope: snapshot.scope,
        userId: snapshot.replyTo,
        agentId: snapshot.id,
        completed: snapshot.status === 'done' || snapshot.status === 'error',
      });
    },
    recover(history) { for (const message of history) this.receive(message); },
    waiting(scope) { return requests.filter((request) => request.scope === scope &&
      request.userId !== undefined && !request.completed).map((request) => request.userId); },
    inspect() { return requests.map((request) => ({ ...request })); },
  };
}
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { createLedger } from '../src/ledger.mjs';

for (const status of ['done', 'error']) {
  test('saved association completes the original request through ' + status, () => {
    const ledger = createLedger();
    ledger.accept('room', 10);
    ledger.restoreMessage({ scope: 'room', id: 11, replyTo: 10, status: 'streaming' });
    ledger.receive({ scope: 'room', id: 11, status });
    assert.deepEqual(ledger.waiting('room'), []);
    assert.equal(ledger.inspect().length, 1);
  });
}
test('normal streaming and duplicate completion retain one terminal request', () => {
  const ledger = createLedger();
  ledger.accept('room', 10);
  ledger.receive({ scope: 'room', id: 11, replyTo: 10, status: 'streaming' });
  assert.deepEqual(ledger.waiting('room'), [10]);
  ledger.receive({ scope: 'room', id: 11, status: 'done' });
  ledger.receive({ scope: 'room', id: 11, status: 'done' });
  ledger.accept('room', 10);
  assert.deepEqual(ledger.waiting('room'), []);
  assert.equal(ledger.inspect().length, 1);
});
test('unassociated completion does not guess the latest question', () => {
  const ledger = createLedger();
  ledger.accept('room', 10);
  ledger.receive({ scope: 'room', id: 99, status: 'done' });
  assert.deepEqual(ledger.waiting('room'), [10]);
});
test('other requests and scopes remain waiting', () => {
  const ledger = createLedger();
  ledger.accept('room', 10);
  ledger.accept('room', 20);
  ledger.accept('other', 10);
  ledger.restoreMessage({ scope: 'room', id: 11, replyTo: 10 });
  ledger.receive({ scope: 'room', id: 11, status: 'done' });
  assert.deepEqual(ledger.waiting('room'), [20]);
  assert.deepEqual(ledger.waiting('other'), [10]);
});
test('known terminal association arriving before acceptance stays terminal', () => {
  const ledger = createLedger();
  ledger.receive({ scope: 'room', id: 11, replyTo: 10, status: 'done' });
  ledger.accept('room', 10);
  assert.deepEqual(ledger.waiting('room'), []);
});
test('explicit history recovery still handles an actually missed signal', () => {
  const ledger = createLedger();
  ledger.accept('room', 10);
  ledger.recover([{ scope: 'room', id: 11, replyTo: 10, status: 'done' }]);
  assert.deepEqual(ledger.waiting('room'), []);
});
# Reply ledger reproduction

One accepted local request occupies the direct-conversation slot until its
correlated completion is recorded. Message content and request completion have
different meanings. Receipt, completion, duplicate delivery and history recovery
may arrive in different orders. Existing associations must survive partial
completion snapshots; unknown associations must remain unknown.

The captured session reached `accept -> stream -> completed`. The transport
delivered each event once, yet the original request remained waiting. An older
installation had saved message associations before its ledger was introduced.
Operations propose a periodic full-history refresh because the existing explicit
recovery call clears the symptom. Inspect the main path before choosing a fix.

The fixture is an in-memory transactional model, not a production SQL engine.
